// The extensions Kobble ships with, as modules (one folder each under
// extensions/): Kobble's own, installed in every factory unless the company
// removes one (Factory is always needed, as it builds everything), and the
// add-ons that connect a service (where work is tracked). Their names and
// lines are words, kept in the page's catalogue by id.
import * as explorations from "../extensions/explorations/index.js";
import * as factory from "../extensions/factory/index.js";
import { githubAddOn } from "../extensions/github/index.js";
import { jiraAddOn } from "../extensions/jira/index.js";
import * as personas from "../extensions/personas/index.js";
import * as releases from "../extensions/releases/index.js";
import * as signals from "../extensions/signals/index.js";
export const KOBBLE_MODULES = [
    factory,
    explorations,
    signals,
    personas,
    releases,
];
export const KOBBLE_EXTENSIONS = KOBBLE_MODULES.map((module) => module.extension);
// The add-ons that ship with the factory, through this GitHub CLI and this
// way of reaching Jira (stand-ins in the tests).
export function addOnModules(cli, fetcher) {
    return [githubAddOn(cli), jiraAddOn(fetcher)];
}
